package com.threattrace.persistence;

import com.threattrace.domain.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import java.util.*;

@Repository
public class CaseRepository {
    private final JdbcTemplate jdbc;
    public CaseRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
    public List<Map<String,Object>> cases(){return jdbc.queryForList("SELECT case_id id, case_name name, classification, is_synthetic synthetic FROM investigation_cases ORDER BY case_id");}
    public List<Map<String,Object>> timeline(int caseId,String category,String certainty){
        StringBuilder sql=new StringBuilder("SELECT e.event_id id,e.case_id caseId,e.occurred_at occurredAt,e.event_type type,e.source_label source,e.description,e.evidence_ref evidenceRef,e.certainty,e.parent_event_id parentId,e.host_label host FROM event_logs e WHERE e.case_id=?");
        List<Object> args=new ArrayList<>();args.add(caseId);if(category!=null&&!category.equals("ALL")){sql.append(" AND e.event_type=?");args.add(category);}if(certainty!=null&&!certainty.equals("ALL")){sql.append(" AND e.certainty=?");args.add(certainty);}sql.append(" ORDER BY e.occurred_at,e.event_id");return jdbc.queryForList(sql.toString(),args.toArray());
    }
    public Map<String,Object> analyticsFeatures(int caseId){
        var rows=jdbc.queryForList("SELECT event_id id,occurred_at occurredAt,event_type type,feature_sequence sequence,feature_target target,feature_behavior behavior,feature_progression progression,certainty,evidence_ref evidenceRef FROM event_logs WHERE case_id=? AND certainty<>'MISSING_TELEMETRY' ORDER BY occurred_at",caseId);
        if(rows.isEmpty())throw new IllegalArgumentException("Case has no observed feature events");
        long first=EventTime.toInstant(rows.get(0).get("occurredAt")).toEpochMilli();List<Map<String,Object>> minimized=new ArrayList<>();for(var row:rows){Map<String,Object> feature=new LinkedHashMap<>(row);long time=EventTime.toInstant(feature.remove("occurredAt")).toEpochMilli();feature.put("relativeSeconds",(time-first)/1000.0);minimized.add(feature);}
        var missing=jdbc.queryForList("SELECT event_id id,evidence_ref evidenceRef FROM event_logs WHERE case_id=? AND certainty='MISSING_TELEMETRY' ORDER BY occurred_at",caseId);
        return Map.of("caseId",caseId,"events",minimized,"missingCount",missing.size(),"missingEvents",missing,"coverageNote","Categorical features and relative intervals only; event descriptions and absolute timestamps are not sent to analytics.");
    }
    public Map<String,Object> event(int id){return jdbc.queryForMap("SELECT e.event_id id,e.case_id caseId,e.occurred_at occurredAt,e.event_type type,e.source_label source,e.description,e.evidence_ref evidenceRef,e.certainty,e.parent_event_id parentId,e.host_label host FROM event_logs e WHERE e.event_id=?",id);}
    public List<Map<String,Object>> hypotheses(int caseId){return jdbc.queryForList("SELECT hypothesis_id id,title,status,confidence,rationale,missing_telemetry missingTelemetry FROM hypotheses WHERE case_id=? ORDER BY hypothesis_id",caseId);}
    public List<com.threattrace.domain.Hypothesis> hypothesisRecords(int caseId){return jdbc.query("SELECT hypothesis_id,title,status,confidence,rationale,missing_telemetry FROM hypotheses WHERE case_id=? ORDER BY hypothesis_id",(rs,n)->new com.threattrace.domain.Hypothesis(rs.getInt("hypothesis_id"),caseId,rs.getString("title"),rs.getString("status"),rs.getDouble("confidence"),rs.getString("rationale"),rs.getString("missing_telemetry")),caseId);}
    public List<Map<String,Object>> evidenceForHypothesis(int id){return jdbc.queryForList("SELECT relation, event_id eventId, note FROM hypothesis_evidence WHERE hypothesis_id=? ORDER BY event_id",id);}
    public List<Map<String,Object>> assets(int caseId){return jdbc.queryForList("SELECT node_id id,label,node_type type,criticality,certainty FROM digital_twin_nodes WHERE case_id=? ORDER BY node_id",caseId);}
    public List<Map<String,Object>> edges(int caseId){return jdbc.queryForList("SELECT edge_id id,from_node_id source,to_node_id target,edge_type type,certainty,description FROM digital_twin_edges WHERE case_id=? ORDER BY edge_id",caseId);}
    public List<Map<String,Object>> strategies(){return jdbc.queryForList("SELECT strategy_id id,label,risk_reduction riskReduction,business_disruption disruption,evidence_impact evidenceImpact,estimated_minutes minutes FROM mitigation_strategies ORDER BY strategy_id");}
    public Map<String,Object> strategy(int id){return jdbc.queryForMap("SELECT strategy_id id,label,risk_reduction riskReduction,business_disruption disruption,evidence_impact evidenceImpact,estimated_minutes minutes FROM mitigation_strategies WHERE strategy_id=?",id);}
    public int saveSimulation(int caseId,String strategy,String result){return jdbc.update("INSERT INTO simulation_runs(case_id,scenario_label,model_version,assumptions,output_json) VALUES(?,?,'twin-1.0','Synthetic topology; reachability is an estimate.',CAST(? AS JSON))",caseId,strategy,result);}
    public int saveComparison(Map<String,Object> result,String digest,Map<String,Object> featuresA,Map<String,Object> featuresB){
        return jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<Integer>)con->{boolean old=con.getAutoCommit();con.setAutoCommit(false);try{
            int a=((Number)result.get("caseA")).intValue(),b=((Number)result.get("caseB")).intValue();if(a>b){int t=a;a=b;b=t;}
            var c=con.prepareStatement("INSERT INTO similarity_comparisons(case_a,case_b,overall_score,method_version,input_digest) VALUES(?,?,?,?,?)",java.sql.Statement.RETURN_GENERATED_KEYS);c.setInt(1,a);c.setInt(2,b);c.setDouble(3,((Number)result.get("overall")).doubleValue());c.setString(4,(String)result.get("methodVersion"));c.setString(5,digest);c.executeUpdate();var keys=c.getGeneratedKeys();keys.next();int id=keys.getInt(1);
            for(var side:List.of(featuresA,featuresB)){String label=((Number)side.get("caseId")).intValue()==a?"A":"B";List<Object> refs=new ArrayList<>((List<?>)side.get("events"));refs.addAll((List<?>)side.get("missingEvents"));for(Object item:refs){Map<?,?> event=(Map<?,?>)item;var in=con.prepareStatement("INSERT INTO comparison_input_events(comparison_id,side,event_id) VALUES(?,?,?)");in.setInt(1,id);in.setString(2,label);in.setInt(3,((Number)event.get("id")).intValue());in.executeUpdate();}}
            for(Object o:(List<?>)result.get("dimensions")){Map<?,?> d=(Map<?,?>)o;Object canonicalMatches=((Number)result.get("caseA")).intValue()==a?d.get("matchedEvents"):d.get("caseBMatchedEvents");var q=con.prepareStatement("INSERT INTO similarity_dimensions(comparison_id,dimension,score,explanation,matched_refs,differing_refs,missing_notes) VALUES(?,?,?,?,CAST(? AS JSON),CAST(? AS JSON),CAST(? AS JSON))");q.setInt(1,id);q.setString(2,((String)d.get("key")).toUpperCase(Locale.ROOT));q.setDouble(3,((Number)d.get("score")).doubleValue());q.setString(4,(String)d.get("explanation"));q.setString(5,new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(canonicalMatches));q.setString(6,new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(d.get("differing")));q.setString(7,new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(d.get("missing")));q.executeUpdate();}
            con.commit();return id;
        }catch(Exception e){con.rollback();throw new IllegalStateException("Could not persist comparison",e);}finally{con.setAutoCommit(old);}});
    }
    public List<Map<String,Object>> packages(){return jdbc.queryForList("SELECT package_id id,case_id caseId,purpose,recipient_label recipient,status,expires_at expiresAt,manifest_hash hash,created_at createdAt FROM evidence_packages ORDER BY package_id DESC");}
    public Map<String,Object> createPackage(int caseId,String purpose,String recipient,List<Integer> ids,String aliasMode){
        return jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<Map<String,Object>>) con->{
            boolean old=con.getAutoCommit();con.setAutoCommit(false);
            try {
                var p=con.prepareStatement("INSERT INTO evidence_packages(case_id,purpose,recipient_label,status,expires_at) VALUES(?,?,?,'DRAFT',DATE_ADD(UTC_TIMESTAMP(),INTERVAL 30 DAY))",java.sql.Statement.RETURN_GENERATED_KEYS);
                p.setInt(1,caseId);p.setString(2,purpose);p.setString(3,recipient);p.executeUpdate();var keys=p.getGeneratedKeys();keys.next();int pid=keys.getInt(1);
                for(Integer id:ids){var q=con.prepareStatement("INSERT INTO package_items(package_id,event_id,redaction_mode) SELECT ?,event_id,? FROM event_logs WHERE event_id=? AND case_id=?");q.setInt(1,pid);q.setString(2,aliasMode);q.setInt(3,id);q.setInt(4,caseId);if(q.executeUpdate()!=1)throw new IllegalArgumentException("Evidence event "+id+" is not in this case");}
                var a=con.prepareStatement("INSERT INTO audit_events(case_id,object_type,object_id,action,actor_label,reason) VALUES(?,'PACKAGE',?,'CREATED','demo-analyst','Synthetic demo package draft')");a.setInt(1,caseId);a.setInt(2,pid);a.executeUpdate();con.commit();return Map.of("id",pid,"status","DRAFT","items",ids.size());
            } catch(Exception e){con.rollback();throw e;} finally {con.setAutoCommit(old);}
        });
    }
    public Map<String,Object> packagePreview(int id){
        var p=jdbc.queryForMap("SELECT package_id id,case_id caseId,purpose,recipient_label recipient,status,expires_at expiresAt,manifest_hash manifestHash FROM evidence_packages WHERE package_id=?",id);
        var approvals=jdbc.queryForList("SELECT reviewer_label reviewer,decision,reason,created_at createdAt FROM package_approvals WHERE package_id=? ORDER BY approval_id",id);p.put("approvals",approvals);
        var modes=jdbc.queryForList("SELECT redaction_mode redactionMode FROM package_items WHERE package_id=? LIMIT 1",id);if(!modes.isEmpty())p.put("redactionMode",modes.get(0).get("redactionMode"));
        var items=jdbc.queryForList("SELECT pi.event_id id,pi.redaction_mode redactionMode,e.occurred_at occurredAt,e.event_type type,e.source_label source,e.description,e.evidence_ref evidenceRef,e.certainty,e.host_label host FROM package_items pi JOIN event_logs e ON e.event_id=pi.event_id WHERE pi.package_id=? ORDER BY e.occurred_at",id);p.put("items",items);return p;
    }
    public void setManifestHash(int id,String hash){jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<Void>)con->{boolean old=con.getAutoCommit();con.setAutoCommit(false);try{var u=con.prepareStatement("UPDATE evidence_packages SET manifest_hash=? WHERE package_id=? AND status='RELEASED'");u.setString(1,hash);u.setInt(2,id);if(u.executeUpdate()!=1)throw new IllegalStateException("Package must remain RELEASED to record its manifest");var q=con.prepareStatement("SELECT case_id FROM evidence_packages WHERE package_id=?");q.setInt(1,id);var rs=q.executeQuery();rs.next();var a=con.prepareStatement("INSERT INTO audit_events(case_id,object_type,object_id,action,actor_label,reason) VALUES(?,'PACKAGE',?,'MANIFEST_HASHED','workflow','SHA-256 generated for redacted JSON passport')");a.setInt(1,rs.getInt(1));a.setInt(2,id);a.executeUpdate();con.commit();return null;}catch(Exception e){con.rollback();throw new IllegalStateException("Could not persist package manifest hash",e);}finally{con.setAutoCommit(old);}});}
    public void submitPackage(int id){jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<Void>) con->{boolean old=con.getAutoCommit();con.setAutoCommit(false);try{var c=con.prepareCall("CALL sp_submit_package_for_review(?)");c.setInt(1,id);c.execute();con.commit();return null;}catch(Exception e){con.rollback();throw e;}finally{con.setAutoCommit(old);}});}
    public void decidePackage(int id,String decision,String reviewer,String reason){if(!decision.equals("APPROVE")&&!decision.equals("REJECT"))throw new IllegalArgumentException("Decision must be APPROVE or REJECT");jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<Void>)con->{boolean old=con.getAutoCommit();con.setAutoCommit(false);try{var state=con.prepareStatement("SELECT status FROM evidence_packages WHERE package_id=? FOR UPDATE");state.setInt(1,id);var rs=state.executeQuery();if(!rs.next()||!"PENDING_REVIEW".equals(rs.getString(1)))throw new IllegalStateException("Package must be pending review");var a=con.prepareStatement("INSERT INTO package_approvals(package_id,reviewer_label,decision,reason) VALUES(?,?,?,?)");a.setInt(1,id);a.setString(2,reviewer);a.setString(3,decision);a.setString(4,reason);a.executeUpdate();if(decision.equals("APPROVE")){var c=con.prepareCall("CALL sp_approve_package_release(?)");c.setInt(1,id);c.execute();}else{jdbc.update("UPDATE evidence_packages SET status='REJECTED' WHERE package_id=? AND status='PENDING_REVIEW'",id);}con.commit();return null;}catch(Exception e){con.rollback();throw e;}finally{con.setAutoCommit(old);}});}
    public List<Map<String,Object>> audit(){return jdbc.queryForList("SELECT audit_id id,case_id caseId,object_type objectType,object_id objectId,action,actor_label actor,reason,created_at createdAt FROM vw_audit_history ORDER BY created_at DESC LIMIT 100");}
}
